 if not (p/'stat').exists(): return {'pid':pid,'original_process_present':False}
 raw=(p/'stat').read_text();f=raw[raw.rfind(')')+2:].split()
 assert int(f[19])==expected_start, 'PID identity mismatch'
 return {'pid':pid,'original_process_present':True,'state':f[0],'ppid':int(f[1]),'start_ticks':int(f[19])}
assert ident(root/'orphan-completion-recovery/watch_final_workers.py')['sha256']=='57287dad0574787e3b868a187acc41db1af97b37172dc75698c9b0942b96d2da'
rows=[]
for run,pid,start,runsha in [('verified-v3-normuon-1e-4',1959407,295778135,'e40f13f27c036d11dbbe735acc62f4a3923954b2e78a5764af3debb809bed56c'),('verified-v3-normuon-3e-3',1959573,295779725,'bf7f25acbbf5cb7bf7d375e040e86a36b6fa085aef12d7335b540c7230010ff6')]:
 r={'run_id':run,'process':process(pid,start),'receipts':{}}
 for suffix in ('process-terminated','artifacts-verified','verification-failed'):
  p=root/'orphan-completion-recovery/receipts'/f'{run}.{suffix}.json'
  if p.exists():
   d=json.loads(p.read_text())
   r['receipts'][suffix]={'path':str(p),**ident(p),'record':d}
   if suffix=='artifacts-verified':
    assert d['whole_run_artifacts_verified'] is True and d['explicit_two_selection_view_audit_passed'] is True
    assert d['run_identity_sha256']==runsha and d['steps']==[782,1563,2345,3126,3907]
    assert d['observer_source_sha256']=='57287dad0574787e3b868a187acc41db1af97b37172dc75698c9b0942b96d2da'
    assert d['process_observation']['pid']==pid and d['process_observation']['start_ticks']==start
    assert d['process_observation']['process_termination_observed_via_pidfd'] is True and d['process_observation']['training_exit_code'] is None
    assert d['original_single_selection_guard_passed'] is False and d['committed_source_release'] is False and d['scientific_completion'] is False
    assert len(d['checkpoints'])==5 and all(len(c['files'])==20 for c in d['checkpoints'])
    assert [c['scheduler_step'] for c in d['deep_checkpoint_checks']]==[782,1563,2345,3126,3907]
    assert all(c['parameter_states']==134 and c['group_parameter_counts']==[88,1,45] for c in d['deep_checkpoint_checks'])
 rows.append(r)
final={}
for rel in ('orphan-completion-recovery/both-final-worker-artifacts-verified.json','backup-receipts/all-60-checkpoints-verified.json'):
 p=root/rel
 if p.exists(): final[rel]={'path':str(p),**ident(p),'record':json.loads(p.read_text())}
print(json.dumps({'observed_at_utc':datetime.now(timezone.utc).isoformat(),'runs':rows,'final_records':final,'observer_process':process(1993005,297067443),'backup_process':process(1990603,296921594),'new_deep_or_payload_rehash':False,'scientific_completion':False}))
